#include "rinkfit/joint_source_append_primal_v1.hpp"
#include <iostream>
#include <fstream>
using namespace rinkfit;
int main(int argc,char**argv){try{
 using namespace source_append_v1;need(argc==3,"configuration and result paths required");const auto cfg=eventio::read_json(argv[1]);const auto&p=cfg.at("representative_source_append_primal_v1");const auto saved=eventio::read_json(pin(cfg.at("representative_continuation_v1")));const auto proof=authorization(cfg,saved.at("source_packet_sha256"),p.at("source_packet").at("sha256"));
 const std::size_t n0=p.at("from_raw_rows"),n=p.at("to_raw_rows");const auto model=eventio::read_json(pin(saved.at("model")));const auto mp=pin(saved.at("explicit_nuisance_manifest"));const auto manifest=eventio::read_json(mp);
 std::ifstream stream(pin(saved.at("checkpoint")));const auto checkpoint=read_checkpoint(stream);need(checkpoint.state.token()==saved.at("state_token")&&checkpoint.runtime_fingerprint==p.at("from_runtime_fingerprint"),"actual old complete token/fingerprint");
 const auto identity=validate_joint_representative_resume_identity_v1(checkpoint,saved,cfg,"new_authenticated_source_fixture",true);need(checkpoint.state.data().root_charts.empty(),"unhandled observed root chart");
 const auto&params=checkpoint.state.data().parameters;const auto nb=model.at("blocks").size();need(params.size()>=nb,"complete physical prefix");
 for(std::size_t i=0;i<nb;++i){const auto v=model.at("blocks").at(i).at("values").get<std::vector<double>>();need(params[i].name==model.at("blocks").at(i).at("name")&&params[i].values.size()==v.size()&&std::memcmp(params[i].values.data(),v.data(),v.size()*8)==0,"actual physical model/CP bytes");}
 std::map<std::string,std::vector<std::uint8_t>>joined;eventio::Json columns=eventio::Json::object();std::vector<std::uint32_t>oldpaths;
 for(const auto&entry:std::vector<std::pair<std::string,std::string>>{{"station","station.f64"},{"row","row.f64"},{"alpha","alpha.f64"},{"path","path.u32"}}){const auto width=entry.first=="path"?4u:8u;const auto&spec=manifest.at("files").at(entry.second);const auto file=mp.parent_path()/entry.second;eventio::verify(file,spec.at("sha256"));const auto old=eventio::bytes(file);need(old.size()==n0*width&&spec.at("size_bytes")==old.size(),"actual full raw prefix bytes");
 const auto tail=raw_column(p.at("tail_source_columns").at(entry.first),n,width,width==4?"<u4":"<f8");auto&next=joined[entry.first];next=old;next.insert(next.end(),tail.begin()+n0*width,tail.end());need(next.size()==n*width&&std::memcmp(next.data(),old.data(),old.size())==0&&std::memcmp(next.data()+old.size(),tail.data()+old.size(),(n-n0)*width)==0,"full prefix/tail byte equivalence");
 columns[entry.first]={{"old_rows",n0},{"new_rows",n-n0},{"old_sha256",spec.at("sha256")},{"combined_sha256",eventio::sha256(next)}};if(width==4){oldpaths.resize(n0);std::memcpy(oldpaths.data(),old.data(),old.size());}}
 need(checkpoint.state.data().discrete.at("finite_material_paths_RLE_u32_v1")==joint_path_RLE(oldpaths),"actual raw path/checkpoint complete equivalence");std::size_t aux=0,motion=0,budget=0,zoom=0;
 for(std::size_t k=nb;k<params.size();++k){const auto&v=params[k];const auto slash=v.name.find('/');const auto family=v.name.substr(0,slash);if(family=="station"||family=="row"||family=="alpha"){const auto i=parameter_index(v.name,slash);need(i<n0&&v.values.size()==1&&std::memcmp(v.values.data(),joined.at(family).data()+8*i,8)==0,"actual CP/raw binary64 mismatch");++aux;}else if(family=="static_motion"){need(v.values.size()==2,"complete motion block");++motion;}else if(v.name=="budget_sq"){need(v.values.size()==1,"complete budget block");++budget;}else if(v.name.find("/numerical_zoom_enclosure")!=std::string::npos){need(v.values.size()==2,"complete zoom enclosure");++zoom;}else need(false,"unknown original parameter family");}
 bool bad_range=false,bad_dtype=false;auto bad=cfg;bad["representative_source_append_primal_v1"]["from_raw_rows"]=n0-1;try{authorization(bad,saved.at("source_packet_sha256"),p.at("source_packet").at("sha256"));}catch(...){bad_range=true;}auto d=p.at("tail_source_columns").at("station");d["dtype"]="<u8";try{raw_column(d,n,8,"<f8");}catch(...){bad_dtype=true;}need(bad_range&&bad_dtype,"invalid append contract accepted");
 eventio::Json report={{"schema","rinkfit.actual_source_append_complete_primal_native_regression.v1"},{"passed",true},{"old_state_token",checkpoint.state.token()},{"old_runtime_fingerprint",checkpoint.runtime_fingerprint},{"old_raw_rows",n0},{"current_raw_rows",n},{"new_source_rows",n-n0},{"physical_blocks",nb},{"checkpoint_auxiliary_parameters_checked",aux},{"motion_latent_blocks_checked",motion},{"budget_blocks_checked",budget},{"zoom_enclosures_checked",zoom},{"columns",columns},{"all_old_raw_prefix_bytes_preserved",true},{"all_new_tail_bytes_equal_authenticated_packet",true},{"wrong_raw_denominator_rejected",bad_range},{"wrong_source_dtype_rejected",bad_dtype},{"old_AL_duals_and_penalty_empty",checkpoint.outer.lambda.empty()&&checkpoint.outer.nu.empty()&&checkpoint.outer.rho==0},{"historical_best_state_preserved_in_original_CP",!checkpoint.best_physical_state.empty()},{"new_objective_identity_check",identity},{"solver_started",false},{"quality_accepted",false}};eventio::atomic_json(argv[2],report);std::cout<<report.dump()<<std::endl;return 0;
 }catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}}
